<?php
declare(strict_types=1);
namespace Brebo\Office\Project\Workspace;
use PDO;
require_once __DIR__.'/Controls.php';
final class Sources {
  private array $tables=[];
  public function __construct(private readonly PDO $db,private readonly string $actor){}
  private function has(string ...$names):bool{foreach($names as $name){if(!array_key_exists($name,$this->tables)){$q=$this->db->prepare($this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'?"SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=?":'SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');$q->execute([$name]);$this->tables[$name]=(int)$q->fetchColumn()===1;}if(!$this->tables[$name])return false;}return true;}
  private function rows(string $sql,array $args=[]):array{$q=$this->db->prepare($sql);$q->execute($args);return $q->fetchAll(PDO::FETCH_ASSOC);}
  private static function money(mixed $v):int{if(!is_string($v))$v=(string)$v;return Controls::cents($v);}
  public function read(int $project,string $today):array{
    $controls=new Controls($this->db,$this->actor);$controls->authorize($project);Controls::date($today);$r=['project_id'=>$project,'today'=>$today,'settings'=>$controls->settings($project),'milestones'=>$controls->milestones($project),'progress'=>$controls->progress($project),'forecast'=>$controls->forecast($project),'finance_allowed'=>$controls->finance(),'finance_write'=>$controls->finance(true),'can_manage'=>false,'clients'=>null,'team'=>null,'planned_seconds'=>null,'approved_seconds'=>null,'finance'=>null,'target'=>null,'buildings'=>null,'housing'=>null,'relations'=>[],'party_sources'=>[]];
    try{$controls->authorize($project,true);$r['can_manage']=true;}catch(\DomainException){}
    $r['project']=$this->rows('SELECT id,code,title,status FROM office_projects WHERE id=?',[$project])[0];
    if($this->has('office_project_dwelling_targets')){$q=$this->db->prepare('SELECT expected_dwelling_count FROM office_project_dwelling_targets WHERE project_id=?');$q->execute([$project]);$value=$q->fetchColumn();if($value!==false)$r['target']=(int)$value;}
    if($this->has('office_buildings','office_project_buildings'))$r['buildings']=$this->rows('SELECT b.id,b.code,b.name FROM office_buildings b JOIN office_project_buildings p ON p.building_id=b.id WHERE p.project_id=? ORDER BY b.name,b.id',[$project]);
    if($this->has('office_project_housing_types','office_housing_types','office_project_buildings'))$r['housing']=$this->rows('SELECT h.name,h.code,p.dwelling_count,p.building_id FROM office_project_housing_types p JOIN office_housing_types h ON h.id=p.housing_type_id AND h.building_id=p.building_id JOIN office_project_buildings b ON b.project_id=p.project_id AND b.building_id=p.building_id WHERE p.project_id=? ORDER BY p.building_id,h.id',[$project]);
    if(getenv('OFFICE_TEST_CRM_ENABLED')==='enabled'&&$this->has('office_crm_assignment_parties','office_crm_relations')){
      $r['clients']=$this->rows("SELECT DISTINCT a.party_role,r.id,r.display_name,r.legal_name,r.email,r.phone,r.street,r.postal_code,r.city FROM office_crm_assignment_parties a JOIN office_crm_relations r ON r.id=a.relation_id WHERE a.assignment_type IN ('project','office_project') AND a.assignment_id=? AND a.party_role IN ('contracting_party','ordering_party','communication_contact','invoice_debtor') AND r.status='active' ORDER BY a.party_role,r.display_name",[(string)$project]);
      foreach($r['clients'] as &$client){$client['contacts']=[];if($this->has('office_crm_relation_contacts','office_crm_contact_people'))$client['contacts']=$this->rows("SELECT p.given_name,p.family_name,p.email,p.phone,c.is_primary FROM office_crm_relation_contacts c JOIN office_crm_contact_people p ON p.id=c.contact_id WHERE c.relation_id=? AND p.status='active' ORDER BY c.is_primary DESC,p.family_name,p.id",[$client['id']]);}unset($client);
      if($r['can_manage']&&getenv('OFFICE_CRM_RELATIONS_WRITE_ENABLED')==='enabled'){$r['relations']=$this->rows("SELECT id,display_name FROM office_crm_relations WHERE status='active' ORDER BY display_name");foreach(['contracting_party','communication_contact'] as $role)$r['party_sources'][$role]=$controls->parties($project,$role);}
    }
    if($this->has('office_inzet_people','office_inzet_project_team'))$r['team']=$this->rows('SELECT p.id,p.display_name,t.role_label,p.active FROM office_inzet_project_team t JOIN office_inzet_people p ON p.id=t.person_id WHERE t.project_id=? ORDER BY p.active DESC,p.display_name,p.id',[$project]);
    if($this->has('office_inzet_shifts')){$r['planned_seconds']=0;$until=(new \DateTimeImmutable($today,new \DateTimeZone('Europe/Amsterdam')))->modify('+1 day')->setTimezone(new \DateTimeZone('UTC'))->getTimestamp();foreach($this->rows("SELECT starts_at,ends_at FROM office_inzet_shifts WHERE project_id=? AND status NOT IN ('cancelled','canceled')",[$project]) as $shift){$a=(new \DateTimeImmutable($shift['starts_at'],new \DateTimeZone('UTC')))->getTimestamp();$b=min($until,(new \DateTimeImmutable($shift['ends_at'],new \DateTimeZone('UTC')))->getTimestamp());$r['planned_seconds']+=max(0,$b-$a);}}
    if($this->has('office_onsite_hours_reviews','office_onsite_event_inbox')){$r['approved_seconds']=0;foreach($this->rows("SELECT h.reviewed_seconds,e.occurred_at_utc FROM office_onsite_hours_reviews h JOIN office_onsite_event_inbox e ON e.event_id=h.in_event_id AND e.person_id=h.person_id AND e.project_id=h.project_id WHERE h.project_id=? AND h.approval_status='approved' AND h.reviewed_seconds>0 AND h.reviewed_seconds<=86400",[(string)$project]) as $hour){$date=(new \DateTimeImmutable($hour['occurred_at_utc'],new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('Europe/Amsterdam'))->format('Y-m-d');if($date<=$today)$r['approved_seconds']+=(int)$hour['reviewed_seconds'];}}
    if($r['finance_allowed']){
      $f=['original_cents'=>null,'accepted_base_cents'=>null,'approved_more_cents'=>null,'approved_less_cents'=>null,'forecast_result_cents'=>null,'sales'=>null,'costs_cents'=>null];
      if($this->has('office_project_contracts')){$contracts=$this->rows("SELECT id,contract_amount,currency,status FROM office_project_contracts WHERE office_project_id=? AND status NOT IN ('cancelled','canceled','void')",[$project]);$f['original_cents']=0;$accepted=[];foreach($contracts as $contract)if($contract['currency']==='EUR'){$f['original_cents']+=self::money($contract['contract_amount']);if(in_array($contract['status'],['signed','accepted','approved','active','confirmed'],true))$accepted[]=$contract;}
        if($accepted){$f['accepted_base_cents']=0;$changesAvailable=$this->has('office_project_change_orders');$f['approved_more_cents']=$changesAvailable?0:null;$f['approved_less_cents']=$changesAvailable?0:null;foreach($accepted as $contract){$f['accepted_base_cents']+=self::money($contract['contract_amount']);if($this->has('office_project_change_orders'))foreach($this->rows("SELECT change_type,amount FROM office_project_change_orders WHERE contract_id=? AND status='approved'",[$contract['id']]) as $change){if($change['change_type']==='more')$f['approved_more_cents']+=self::money($change['amount']);elseif($change['change_type']==='less')$f['approved_less_cents']+=self::money($change['amount']);}}
          if($changesAvailable&&$r['forecast'])$f['forecast_result_cents']=$f['accepted_base_cents']+$f['approved_more_cents']-$f['approved_less_cents']-(int)$r['forecast']['direct_cents']-(int)$r['forecast']['labor_cents']-(int)$r['forecast']['overhead_cents'];
        }
      }
      if($this->has('office_finance_sales_invoice'))$f['sales']=$this->rows("SELECT id,invoice_number,invoice_date,due_date,net_cents,gross_cents,paid_cents,status FROM office_finance_sales_invoice WHERE office_project_id=? ORDER BY invoice_date DESC,id DESC",[$project]);
      if($this->has('office_finance_postings','office_finance_posting_lines')){$q=$this->db->prepare("SELECT COALESCE(SUM(l.net_cents),0) FROM office_finance_posting_lines l JOIN office_finance_postings p ON p.id=l.posting_id WHERE l.office_project_id=? AND p.status='booked' AND p.booking_date<=?");$q->execute([$project,$today]);$f['costs_cents']=(int)$q->fetchColumn();}$r['finance']=$f;
    }
    $r['planned_percent_units']=null;$r['overdue_days']=null;foreach($r['milestones'] as $m)if((int)$m['archived']===0){if($m['planned_date']<=$today&&$m['target_units']!==null)$r['planned_percent_units']=(int)$m['target_units'];if($m['actual_date']===null&&$m['planned_date']<$today){$days=(int)(new \DateTimeImmutable($today))->diff(new \DateTimeImmutable($m['planned_date']))->days;$r['overdue_days']=max($r['overdue_days']??0,$days);}}
    $r['tasks']=$controls->tasks($project);
    return $r;
  }
}
